<script setup>
import AppShell from '../../Components/Ui/AppShell.vue'
import de from '../../i18n/de'
import { router, useForm } from '@inertiajs/vue3'
import { computed, ref } from 'vue'

const props = defineProps({ group: Object, workspace: Object, groupOptions: Array, holidayPeriods: Array })
const curriculumOpen = ref(true)
const expandedUnits = ref([])
const editorLesson = ref(null)
const phaseEditor = ref(null)
const newUnitOpen = ref(false)
const dragOverSlot = ref(null)
const curriculumDropActive = ref(false)
const draggingCurriculum = ref(false)
const draggingScheduledItem = ref(false)
const unscheduleDropActive = ref(false)
const slotMenu = ref(null)
const newUnit = useForm({ title: '', notes: '' })
const slotsByDate = computed(() => props.workspace.slots.reduce((groups, slot) => { (groups[slot.date] ||= []).push(slot); return groups }, {}))
const curricula = computed(() => props.workspace.curricula.flatMap(curriculum => curriculum.versions.flatMap(version => version.topics.map(topic => ({ ...topic, curriculum_title: curriculum.title })))))
const holidays = computed(() => (props.holidayPeriods ?? []).map(holiday => ({ ...holiday, starts_on: String(holiday.starts_on).slice(0, 10), ends_on: String(holiday.ends_on).slice(0, 10) })))
const planningEntries = computed(() => [...Object.entries(slotsByDate.value).map(([date, slots]) => ({ type: 'day', date, slots })), ...holidays.value.map(holiday => ({ type: 'holiday', date: holiday.starts_on, holiday }))].sort((left, right) => left.date.localeCompare(right.date) || (left.type === 'holiday' ? -1 : 1)))
const isExpanded = unit => expandedUnits.value.includes(unit.id)
const toggleUnit = unit => { expandedUnits.value = isExpanded(unit) ? expandedUnits.value.filter(id => id !== unit.id) : [...expandedUnits.value, unit.id] }
const statusClass = slot => ({ free: 'text-bg-light', buffer: 'text-bg-info', absent: 'text-bg-danger', cancelled: 'text-bg-warning', blocked: 'text-bg-secondary' }[slot.status] ?? 'text-bg-light')
const statusLabel = slot => ({ free: de.available, buffer: de.buffer, absent: de.absent, cancelled: de.cancelled, blocked: de.blocked }[slot.status] ?? slot.status)
const slotStatusOptions = [{ value: 'free', label: de.available }, { value: 'buffer', label: de.buffer }, { value: 'absent', label: de.absent }, { value: 'cancelled', label: de.cancelled }, { value: 'blocked', label: de.blocked }]
const formatDate = value => { const dateValue = String(value ?? ''); const date = /^\d{4}-\d{2}-\d{2}$/.test(dateValue) ? new Date(`${dateValue}T12:00:00`) : new Date(dateValue); return Number.isNaN(date.getTime()) ? dateValue : date.toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' }) }
const competencyText = competency => { const number = competency.external_identifier || competency.number || competency.education_plan_competency?.external_identifier || competency.education_plan_competency?.number; const text = competency.local_wording || competency.education_plan_competency?.text || competency.text || competency.raw_text || (competency.display && competency.display !== number ? competency.display : null) || de.noCompetencyText; return number ? `${number} – ${text}` : text }
function take(topic) { router.post(`/jahresplanung/${props.group.id}/curriculum-themen/${topic.id}/uebernehmen`) }
function createUnit() { newUnit.post(`/jahresplanung/${props.group.id}/eigene-einheiten`, { onSuccess: () => { newUnitOpen.value = false; newUnit.reset() } }) }
function addLesson(unit) { useForm({ title: `${unit.title} – neue Stunde`, duration: 1 }).post(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/stunden`) }
function schedule(lesson, slot = null) { useForm({ schedule_slot_id: slot?.id ?? null }).post(`/jahresplanung/${props.group.id}/lessons/${lesson.id}/einplanen`) }
function scheduleUnit(unit, slot = null) { useForm({ schedule_slot_id: slot?.id ?? null }).post(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/einplanen`) }
function unscheduleLesson(lesson) { useForm({}).delete(`/jahresplanung/${props.group.id}/lessons/${lesson.id}/einplanung`) }
function unscheduleUnit(unit) { useForm({}).delete(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/einplanung`) }
function dragScheduledLesson(event, lesson) { draggingScheduledItem.value = true; event.dataTransfer.setData('application/json', JSON.stringify({ type: 'lesson', lesson })) }
function dragScheduledUnit(event, unit) { draggingScheduledItem.value = true; event.dataTransfer.setData('application/json', JSON.stringify({ type: 'unit', unit })) }
function endScheduledDrag() { draggingScheduledItem.value = false; unscheduleDropActive.value = false }
function dropToRemove(event) { endScheduledDrag(); const item = JSON.parse(event.dataTransfer.getData('application/json')); if (item.type === 'unit') unscheduleUnit(item.unit); else if (item.type === 'lesson') unscheduleLesson(item.lesson) }
function reorder(unit, index, direction) { const ids = unit.lessons.map(lesson => lesson.id); const target = index + direction; if (target < 0 || target >= ids.length) return; [ids[index], ids[target]] = [ids[target], ids[index]]; useForm({ lesson_ids: ids }).put(`/jahresplanung/${props.group.id}/eigene-einheiten/${unit.id}/stunden/reihenfolge`) }
function selectSlotStatus(slot, status) { slotMenu.value = null; useForm({ status, label: slot.label, notes: slot.notes }).put(`/jahresplanung/${props.group.id}/slots/${slot.id}`) }
function editLesson(lesson) { editorLesson.value = { ...lesson, unit: props.workspace.units.find(unit => unit.lessons.some(item => item.id === lesson.id)), competency_ids: lesson.competencies?.map(competency => competency.id) ?? [] } }
function saveLesson() {
    const lessonForm = useForm({ title: editorLesson.value.title, duration: editorLesson.value.duration, learning_goals: editorLesson.value.learning_goals, materials: editorLesson.value.materials, homework: editorLesson.value.homework, assessment_note: editorLesson.value.assessment_note, notes: editorLesson.value.notes })
    lessonForm.put(`/jahresplanung/${props.group.id}/lessons/${editorLesson.value.id}`, { onSuccess: () => { useForm({ competency_ids: editorLesson.value.competency_ids ?? [] }).put(`/jahresplanung/${props.group.id}/lessons/${editorLesson.value.id}/kompetenzen`, { onSuccess: () => { editorLesson.value = null } }) } })
}
function canDrop(slot) { return ['free', 'buffer'].includes(slot.status) && !slot.scheduled_lesson }
function dropOnSlot(event, slot) { dragOverSlot.value = null; if (!canDrop(slot)) return; const item = JSON.parse(event.dataTransfer.getData('application/json')); if (item.type === 'unit') scheduleUnit(item.unit, slot); else if (item.type === 'lesson') schedule(item.lesson, slot) }
function dragOver(event, slot) { if (canDrop(slot)) { event.preventDefault(); dragOverSlot.value = slot.id } }
function leaveSlot(slot) { if (dragOverSlot.value === slot.id) dragOverSlot.value = null }
function dragLesson(event, lesson) { event.dataTransfer.setData('application/json', JSON.stringify(lesson)) }
function dragPlanningLesson(event, lesson) { event.dataTransfer.setData('application/json', JSON.stringify({ type: 'lesson', lesson })) }
function dragUnit(event, unit) { event.dataTransfer.setData('application/json', JSON.stringify({ type: 'unit', unit })) }
function dragTopic(event, topic) { event.dataTransfer.setData('application/json', JSON.stringify({ curriculum_topic_id: topic.id })) }
function dragCurriculum(event, topic) { draggingCurriculum.value = true; curriculumDropActive.value = true; dragTopic(event, topic) }
function endCurriculumDrag() { draggingCurriculum.value = false; curriculumDropActive.value = false }
function dragOverCurriculum(event) { if (draggingCurriculum.value) { event.preventDefault(); curriculumDropActive.value = true } }
function dropTopic(event) { endCurriculumDrag(); const value = JSON.parse(event.dataTransfer.getData('application/json')); if (value.curriculum_topic_id) take(curricula.value.find(topic => topic.id === value.curriculum_topic_id)) }
</script>

<template>
    <AppShell>
        <template #toolbar>
            <a href="/jahresplanung" class="btn btn-sm btn-light" :title="de.close" :aria-label="de.close"><i class="bi bi-x-lg" aria-hidden="true"></i></a>
            <button class="btn btn-sm btn-outline-secondary" type="button" :title="de.undoReflow" :aria-label="de.undoReflow" @click="router.post(`/jahresplanung/${group.id}/reflow/rueckgaengig`)"><i class="bi bi-arrow-counterclockwise" aria-hidden="true"></i></button>
            <label class="visually-hidden" for="active-group">{{ de.activeTeachingGroup }}</label>
            <select id="active-group" class="form-select form-select-sm" :aria-label="de.activeTeachingGroup" :value="group.id" @change="router.visit(`/jahresplanung/${$event.target.value}`)"><option v-for="option in groupOptions" :key="option.id" :value="option.id">{{ option.name }} · {{ option.school_year.name }}</option></select>
            <span class="small text-muted d-none d-md-inline">{{ group.school_year.name }}</span>
        </template>
        <div class="container-fluid px-3 py-4">
            <h1 class="h2">{{ de.yearPlans }}</h1>
            <div v-if="$page.props.flash?.success" class="alert alert-success" role="status">{{ $page.props.flash.success }}</div>
            <div v-if="$page.props.flash?.warning" class="alert alert-warning" role="alert">{{ $page.props.flash.warning }}</div>
            <div class="small text-muted mb-3">{{ group.school.name }} · {{ group.school_year.name }} · {{ de.coverage }}: {{ workspace.coverage.curriculum_covered }}/{{ workspace.coverage.curriculum_total }} · {{ workspace.coverage.education_plan_lesson }} {{ de.competenciesInLessons }}</div>
            <div class="year-planning-grid" :class="{ 'curriculum-collapsed': !curriculumOpen }">
                <section class="planning-column planning-year" aria-labelledby="year-plan-heading">
                    <div class="d-flex justify-content-between align-items-center mb-2"><h2 id="year-plan-heading" class="h5 mb-0">{{ de.yearPlanColumn }}</h2><span class="badge text-bg-light">{{ workspace.slots.length }}</span></div><p class="small text-muted">{{ de.yearPlanQuestion }}</p>
                    <template v-for="entry in planningEntries" :key="`${entry.type}-${entry.date}-${entry.holiday?.id ?? ''}`">
                        <div v-if="entry.type === 'holiday'" class="holiday-divider"><i class="bi bi-sun me-1" aria-hidden="true"></i><strong>{{ entry.holiday.name || de.holidays }}</strong><span class="small ms-2">{{ formatDate(entry.holiday.starts_on) }} – {{ formatDate(entry.holiday.ends_on) }}</span></div>
                        <div v-else class="planning-day"><h3 class="h6 mb-2">{{ formatDate(entry.date) }}</h3><div v-for="slot in entry.slots" :key="slot.id" class="planning-slot" :class="{ 'slot-blocked': slot.status !== 'free' && slot.status !== 'buffer', 'drop-ready': dragOverSlot === slot.id }" @dragover="dragOver($event, slot)" @dragleave="leaveSlot(slot)" @drop="dropOnSlot($event, slot)"><div class="d-flex align-items-center gap-2"><span class="small text-muted">{{ slot.period_number }}. {{ de.period }}</span><template v-if="slot.scheduled_lesson"><span class="drag-handle" draggable="true" :title="de.dragScheduledUnit" :aria-label="de.dragScheduledUnit" @dragstart="dragScheduledUnit($event, slot.scheduled_lesson.lesson.unit)" @dragend="endScheduledDrag"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><span class="drag-handle" draggable="true" :title="de.dragScheduledLesson" :aria-label="de.dragScheduledLesson" @dragstart="dragScheduledLesson($event, slot.scheduled_lesson.lesson)" @dragend="endScheduledDrag"><i class="bi bi-grip-horizontal" aria-hidden="true"></i></span></template><span class="flex-grow-1 text-truncate">{{ slot.scheduled_lesson?.lesson?.title || de.available }}</span><span v-if="slot.scheduled_lesson" class="small text-truncate">{{ slot.scheduled_lesson.lesson.unit.title }}</span><div class="dropdown"><button class="btn btn-sm btn-link p-0" type="button" :title="de.changeSlotStatus" :aria-label="de.changeSlotStatus" :aria-expanded="slotMenu === slot.id" @click.stop="slotMenu = slotMenu === slot.id ? null : slot.id"><span class="badge" :class="statusClass(slot)">{{ statusLabel(slot) }}</span></button><div v-if="slotMenu === slot.id" class="dropdown-menu show dropdown-menu-end p-1"><button v-for="option in slotStatusOptions" :key="option.value" class="dropdown-item rounded small" type="button" @click="selectSlotStatus(slot, option.value)">{{ option.label }}</button></div></div></div></div></div>
                    </template>
                    <div v-if="!planningEntries.length" class="text-muted small">{{ de.noScheduleSlots }}</div>
                </section>
                <section class="planning-column planning-units" :class="{ 'curriculum-drop-ready': curriculumDropActive }" aria-labelledby="units-heading" @dragover="dragOverCurriculum" @dragleave="curriculumDropActive = false" @drop="dropTopic">
                    <div class="d-flex justify-content-between align-items-center mb-2"><h2 id="units-heading" class="h5 mb-0">{{ de.myTeachingUnits }}</h2><button class="btn btn-sm btn-outline-primary" type="button" @click="newUnitOpen = true">{{ de.addUnit }}</button></div><p class="small text-muted">{{ de.myUnitsQuestion }}</p><div v-if="draggingScheduledItem" class="unschedule-drop-zone" :class="{ 'drop-ready': unscheduleDropActive }" @dragover.prevent="unscheduleDropActive = true" @dragleave="unscheduleDropActive = false" @drop="dropToRemove"><i class="bi bi-trash3 me-1" aria-hidden="true"></i>{{ de.removeFromPlanDropHint }}</div>
                    <div v-if="!workspace.units.length" class="text-muted small">{{ de.noTeachingUnits }}</div>
                    <article v-for="unit in workspace.units" :key="unit.id" class="card mb-2 planning-card"><div class="card-body p-3"><div class="d-flex align-items-start gap-2"><span class="drag-handle" draggable="true" :title="de.dragUnit" :aria-label="de.dragUnit" @dragstart="dragUnit($event, unit)"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><button class="btn btn-sm btn-link p-0" type="button" :aria-expanded="isExpanded(unit)" @click="toggleUnit(unit)"><i :class="isExpanded(unit) ? 'bi bi-chevron-down' : 'bi bi-chevron-right'" aria-hidden="true"></i><span class="visually-hidden">{{ de.expandUnit }}</span></button><div class="flex-grow-1"><strong>{{ unit.title }}</strong><div class="small text-muted">{{ unit.source_curriculum_topic ? `${de.sourceCurriculum}: ${unit.source_curriculum_topic.title}` : de.ownUnit }} · {{ unit.lessons.length }} {{ de.lessons }}</div></div><button class="btn btn-sm btn-outline-primary" type="button" @click="addLesson(unit)">{{ de.addLesson }}</button></div><div v-if="isExpanded(unit)" class="mt-3 ps-3"><div v-if="!unit.lessons.length" class="small text-muted">{{ de.noLessons }}</div><div v-for="(lesson, index) in unit.lessons" :key="lesson.id" class="lesson-row"><div class="d-flex align-items-center gap-2"><span class="drag-handle" draggable="true" :title="de.dragLesson" :aria-label="de.dragLesson" @dragstart="dragPlanningLesson($event, lesson)"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><span class="flex-grow-1"><strong>{{ lesson.title }}</strong><span class="small text-muted ms-2">{{ lesson.duration }} {{ de.hours.toLowerCase() }}</span></span><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.moveUp" :aria-label="de.moveUp" @click="reorder(unit, index, -1)"><i class="bi bi-arrow-up" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.moveDown" :aria-label="de.moveDown" @click="reorder(unit, index, 1)"><i class="bi bi-arrow-down" aria-hidden="true"></i></button><button class="btn btn-sm btn-outline-secondary" type="button" :title="de.editLesson" :aria-label="de.editLesson" @click="editLesson(lesson)"><i class="bi bi-pencil-square" aria-hidden="true"></i><span class="visually-hidden">{{ de.editLesson }}</span></button></div><div class="small text-muted">{{ lesson.scheduled_lessons?.length ?? 0 }}/{{ lesson.duration }} {{ de.slotsPlanned }}</div></div></div></div></article>
                </section>
                <section v-if="curriculumOpen" class="planning-column planning-curricula" aria-labelledby="curricula-heading"><div class="d-flex justify-content-between align-items-center mb-2"><h2 id="curricula-heading" class="h5 mb-0">{{ de.curricula }}</h2><button class="btn btn-sm btn-outline-secondary" type="button" :aria-label="de.collapseCurriculum" :title="de.collapseCurriculum" @click="curriculumOpen = false"><i class="bi bi-layout-sidebar-inset-reverse" aria-hidden="true"></i></button></div><p class="small text-muted">{{ de.curriculumQuestion }}</p><div v-for="topic in curricula" :key="topic.id" class="card mb-2 planning-card"><div class="card-body p-3"><span class="drag-handle" draggable="true" :title="de.dragCurriculum" :aria-label="de.dragCurriculum" @dragstart="dragCurriculum($event, topic)" @dragend="endCurriculumDrag"><i class="bi bi-grip-vertical" aria-hidden="true"></i></span><strong>{{ topic.title }}</strong><div class="small text-muted">{{ topic.curriculum_title }} · {{ topic.hours || 1 }} {{ de.hours.toLowerCase() }} · {{ topic.competencies.length }} {{ de.competencies }}</div><details class="mt-2"><summary class="small">{{ de.showCompetencies }}</summary><ul class="small mb-0 ps-3"><li v-for="competency in topic.competencies" :key="competency.id">{{ competencyText(competency) }}</li></ul></details></div></div></section>
                <button v-else class="btn btn-sm btn-outline-secondary curriculum-open-button" type="button" @click="curriculumOpen = true">{{ de.showCurricula }}</button>
            </div>
        </div>
        <div v-if="newUnitOpen" class="roo-modal-backdrop" role="presentation" @click.self="newUnitOpen = false"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.addUnit"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.addUnit }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="newUnitOpen = false"></button></div><form @submit.prevent="createUnit"><label class="form-label" for="new-unit-title">{{ de.unitTitle }}</label><input id="new-unit-title" v-model="newUnit.title" class="form-control" required><label class="form-label mt-2" for="new-unit-notes">{{ de.notes }}</label><textarea id="new-unit-notes" v-model="newUnit.notes" class="form-control" rows="3"></textarea><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="newUnitOpen = false">{{ de.cancel }}</button><button class="btn btn-primary" type="submit">{{ de.save }}</button></div></form></div></div></section></div>
        <div v-if="editorLesson" class="roo-modal-backdrop" role="presentation" @click.self="editorLesson = null"><section class="roo-modal" role="dialog" aria-modal="true" :aria-label="de.editLesson"><div class="card border-0"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h5 mb-0">{{ de.editLesson }}</h2><button class="btn-close" type="button" :aria-label="de.close" @click="editorLesson = null"></button></div><label class="form-label">{{ de.lessonTitle }}</label><input v-model="editorLesson.title" class="form-control"><label class="form-label mt-2">{{ de.lessonDuration }}</label><input v-model="editorLesson.duration" type="number" min="1" class="form-control"><label class="form-label mt-2">{{ de.learningGoals }}</label><textarea v-model="editorLesson.learning_goals" class="form-control" rows="3"></textarea><label class="form-label mt-2">{{ de.materials }}</label><textarea v-model="editorLesson.materials" class="form-control" rows="3"></textarea><div v-if="editorLesson.unit?.competencies?.length" class="mt-3"><span class="form-label d-block">{{ de.competencies }}</span><label v-for="competency in editorLesson.unit.competencies" :key="competency.id" class="form-check"><input v-model="editorLesson.competency_ids" class="form-check-input" type="checkbox" :value="competency.id"><span class="form-check-label small">{{ competencyText(competency) }}</span></label></div><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="editorLesson = null">{{ de.cancel }}</button><button class="btn btn-primary" type="button" @click="saveLesson">{{ de.saveChanges }}</button></div><hr><h3 class="h6">{{ de.phases }}</h3><button v-for="phase in editorLesson.phases" :key="phase.id" class="btn btn-sm btn-outline-secondary me-1" type="button" @click="phaseEditor = phase">{{ phase.title }}</button></div></div></section></div>
        <aside v-if="phaseEditor" class="offcanvas offcanvas-end show" tabindex="-1" aria-modal="true" role="dialog"><div class="offcanvas-header"><h2 class="h5 mb-0">{{ de.phaseEditor }}</h2><button type="button" class="btn-close" :aria-label="de.close" @click="phaseEditor = null"></button></div><div class="offcanvas-body"><form @submit.prevent="useForm(phaseEditor).put(`/jahresplanung/${group.id}/phasen/${phaseEditor.id}`, { onSuccess: () => { phaseEditor = null } })"><label class="form-label">{{ de.phaseTitle }}</label><input v-model="phaseEditor.title" class="form-control"><label class="form-label mt-2">{{ de.description }}</label><textarea v-model="phaseEditor.description" class="form-control" rows="5"></textarea><button class="btn btn-primary mt-3" type="submit">{{ de.saveChanges }}</button></form></div></aside>
    </AppShell>
</template>
